const layer = document.createElement('gauge-bar');
const root = layer.attachShadow({ mode: 'closed' });
const bar = document.createElement('div'), chip = document.createElement('div');
root.append(Object.assign(document.createElement('style'), { textContent: ':host{all:initial}div{position:fixed;left:0;z-index:2147483646;pointer-events:none}.b{height:var(--t);background:' + APP.accent + ';box-shadow:0 0 10px rgba(' + APP.rgb + ',.7);transition:width .1s linear}.c{right:12px;padding:4px 9px;border-radius:9px;font:600 11px/1.2 system-ui,sans-serif;backdrop-filter:blur(10px)}' }), bar, chip);
bar.className = 'b'; chip.className = 'c';
document.documentElement.append(layer);
let done = false;
FEATURES.paint = () => {
    const s = S.settings, el = document.scrollingElement || document.documentElement;
    const room = el.scrollHeight - innerHeight, words = (document.body?.innerText || '').split(/\s+/).length;
    const long = s.enabled && room > innerHeight && words > 400, f = long ? Math.min(1, el.scrollTop / room) : 0;
    bar.hidden = !(long && s.bar); chip.hidden = !(long && s.time);
    bar.style.cssText = `--t:${s.thick}px;width:${f * 100}%;${s.edge}:0`;
    chip.style.cssText = `${s.edge}:${s.thick + 8}px;background:${isDark() ? 'rgba(22,22,28,.8)' : 'rgba(255,255,255,.84)'};color:${isDark() ? '#f2f2f5' : '#1d1d1f'}`;
    chip.textContent = Math.max(1, Math.round(words * (1 - f) / +s.speed)) + ' min left';
    if (long && f > .98 && !done) { done = true; COUNTS.bump('finished'); }
};
addEventListener('scroll', () => FEATURES.paint(), { passive: true });
addEventListener('resize', () => FEATURES.paint());
